const raw = String($json.url || '').trim();
const url = /^https?:\/\//i.test(raw) ? raw : 'https://' + raw;
const m = url.match(/^(https?):\/\/([a-z0-9.-]+\.[a-z]{2,})(:\d+)?([\/?#][^\s]*)?$/i);
if (!m || /\s/.test(raw)) return [{ json: { ok: false, url: raw } }];
const origin = `${m[1].toLowerCase()}://${m[2].toLowerCase()}${m[3] || ''}`;
return [{ json: { ok: true, url: origin + (m[4] || '/'), origin, keyword: String($json.keyword || '').trim() } }];

// URL helpers (no dependency on the URL global, which some n8n sandboxes lack)
const splitUrl = u => { const m = String(u || '').trim().match(/^(https?):\/\/([^\/?#\s]+)([^#\s]*)/i); return m ? { origin: `${m[1].toLowerCase()}://${m[2].toLowerCase()}`, host: m[2].toLowerCase(), path: (m[3] || '/').split('?')[0] || '/', full: `${m[1].toLowerCase()}://${m[2].toLowerCase()}${m[3] || '/'}` } : null; };
const resolveUrl = (h, base) => { h = String(h || '').trim(); const b = splitUrl(base); if (!b) return ''; if (/^https?:\/\//i.test(h)) return h.split('#')[0]; if (h.startsWith('//')) return (b.origin.split(':')[0] + ':' + h).split('#')[0]; if (h.startsWith('/')) return (b.origin + h).split('#')[0]; const dir = b.path.replace(/[^\/]*$/, ''); return (b.origin + dir + h).split('#')[0].replace(/\/\.\//g, '/'); };
function analyse(html, url, status, keyword, robotsTxt) {
  html = String(html || '');
  const strip = s => String(s || '').replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&quot;/g, '"').replace(/&#39;|&rsquo;/g, "'").replace(/&#x([0-9a-f]+);/gi, (m, h) => String.fromCharCode(parseInt(h, 16))).replace(/&#(\d+);/g, (m, d) => String.fromCharCode(Number(d))).replace(/\s+/g, ' ').trim();
  const attr = (tag, name) => { const m = tag.match(new RegExp(name + '\\s*=\\s*("([^"]*)"|\'([^\']*)\'|([^\\s>]+))', 'i')); return m ? (m[2] ?? m[3] ?? m[4] ?? '') : null; };
  const metas = html.match(/<meta\b[^>]*>/gi) || [];
  const meta = key => { const t = metas.find(m => (attr(m, 'name') || attr(m, 'property') || '').toLowerCase() === key); return t ? strip(attr(t, 'content')) : ''; };
  const links = html.match(/<link\b[^>]*>/gi) || [];
  const title = strip((html.match(/<title[^>]*>([\s\S]*?)<\/title>/i) || [])[1]);
  const description = meta('description');
  const canonicalTag = links.find(l => /rel\s*=\s*["']?canonical/i.test(l));
  const canonical = canonicalTag ? attr(canonicalTag, 'href') : '';
  const robots = meta('robots').toLowerCase();
  const h1s = (html.match(/<h1\b[^>]*>[\s\S]*?<\/h1>/gi) || []).map(strip).filter(Boolean);
  const h2s = (html.match(/<h2\b[^>]*>[\s\S]*?<\/h2>/gi) || []).map(strip).filter(Boolean);
  const body = (html.match(/<body[^>]*>([\s\S]*)<\/body>/i) || [, html])[1]
    .replace(/<script[\s\S]*?<\/script>/gi, ' ').replace(/<style[\s\S]*?<\/style>/gi, ' ').replace(/<noscript[\s\S]*?<\/noscript>/gi, ' ')
    .replace(/<(nav|footer|header)\b[\s\S]*?<\/\1>/gi, ' ');
  const text = strip(body);
  const words = text ? text.split(' ').length : 0;
  const imgs = html.match(/<img\b[^>]*>/gi) || [];
  const noAlt = imgs.filter(i => { const a = attr(i, 'alt'); return a === null || (!a.trim() && !/role=["']presentation/i.test(i)); }).length;
  let origin = '', path = '/';
  const su = splitUrl(url); if (su) { origin = su.origin; path = su.path; }
  const hrefs = (html.match(/<a\b[^>]*href\s*=\s*["'][^"']+["'][^>]*>/gi) || []).map(a => attr(a, 'href')).filter(h => h && !/^(#|mailto:|tel:|javascript:)/i.test(h));
  const abs = hrefs.map(h => resolveUrl(h, url)).filter(Boolean);
  const internal = [...new Set(abs.filter(h => h.startsWith(origin)))];
  const external = [...new Set(abs.filter(h => !h.startsWith(origin)))];
  const lang = (html.match(/<html\b[^>]*\blang\s*=\s*["']?([a-zA-Z-]+)/i) || [])[1] || '';
  const viewport = metas.some(m => (attr(m, 'name') || '').toLowerCase() === 'viewport');
  const jsonLd = (html.match(/<script[^>]*application\/ld\+json[^>]*>([\s\S]*?)<\/script>/gi) || []);
  const schemaTypes = [...new Set(jsonLd.map(s => (s.match(/"@type"\s*:\s*"([^"]+)"/g) || []).map(t => t.split('"')[3])).flat())].slice(0, 6);
  // robots.txt: is this path disallowed for all crawlers? is a sitemap declared?
  let disallowed = false, sitemapDeclared = false;
  if (robotsTxt) {
    sitemapDeclared = /^\s*sitemap\s*:/im.test(robotsTxt);
    let applies = false;
    for (const line of String(robotsTxt).split(/\r?\n/)) {
      const [k, ...rest] = line.split(':'); const v = rest.join(':').trim(); const key = (k || '').trim().toLowerCase();
      if (key === 'user-agent') applies = v === '*';
      else if (applies && key === 'disallow' && v && path.startsWith(v.replace(/\*.*$/, ''))) disallowed = true;
    }
  }
  const kw = String(keyword || '').toLowerCase().trim();
  const has = s => kw && String(s || '').toLowerCase().includes(kw);
  const C = [];
  const add = (id, label, ok, weight, detail, warn = false) => C.push({ id, label, result: ok ? 'pass' : (warn ? 'warn' : 'fail'), weight, detail });
  add('status', 'Page returns HTTP 200', status === 200, 10, `HTTP ${status}`);
  add('https', 'Served over HTTPS', url.startsWith('https://'), 5, url.startsWith('https://') ? 'HTTPS' : 'Not HTTPS');
  add('indexable', 'Page is indexable (no noindex)', !robots.includes('noindex'), 10, robots || 'no robots meta');
  add('robots', 'Not blocked by robots.txt', !disallowed, 8, disallowed ? 'Disallowed for all crawlers' : 'Allowed');
  add('title', 'Title tag 30-60 characters', title.length >= 30 && title.length <= 60, 8, title ? `${title.length} chars` : 'Missing', !!title);
  add('meta', 'Meta description 70-160 characters', description.length >= 70 && description.length <= 160, 6, description ? `${description.length} chars` : 'Missing', !!description);
  add('h1', 'Exactly one H1', h1s.length === 1, 6, `${h1s.length} H1 tag(s)`, h1s.length > 1);
  add('h2', 'Uses H2 subheadings', h2s.length >= 2, 3, `${h2s.length} H2 tag(s)`, h2s.length === 1);
  add('words', 'At least 300 words of content', words >= 300, 6, `${words} words`, words >= 150);
  add('alt', 'Images have alt text', noAlt === 0, 4, `${noAlt} of ${imgs.length} image(s) missing alt`, noAlt <= 2);
  add('canonical', 'Canonical tag present', !!canonical, 5, canonical || 'Missing');
  add('viewport', 'Mobile viewport tag', viewport, 5, viewport ? 'Present' : 'Missing');
  add('lang', 'html lang attribute', !!lang, 2, lang || 'Missing');
  add('og', 'Open Graph title and image', !!meta('og:title') && !!meta('og:image'), 3, meta('og:image') ? 'Present' : 'og:image missing', !!meta('og:title'));
  add('schema', 'Structured data (JSON-LD)', jsonLd.length > 0, 3, schemaTypes.join(', ') || 'None');
  add('internal', 'At least 3 internal links', internal.length >= 3, 4, `${internal.length} internal, ${external.length} external`);
  add('sitemap', 'Sitemap declared in robots.txt', sitemapDeclared, 2, sitemapDeclared ? 'Declared' : (robotsTxt ? 'Not declared' : 'No robots.txt'), true);
  if (kw) {
    add('kw_title', 'Keyword in title', has(title), 6, kw);
    add('kw_h1', 'Keyword in H1', h1s.some(has), 4, kw);
    add('kw_meta', 'Keyword in meta description', has(description), 3, kw, true);
    add('kw_intro', 'Keyword in first 100 words', has(text.split(' ').slice(0, 100).join(' ')), 3, kw, true);
    add('kw_url', 'Keyword words in URL', kw.split(/\s+/).every(p => path.toLowerCase().includes(p)), 2, path, true);
  }
  const total = C.reduce((s, c) => s + c.weight, 0);
  const got = C.reduce((s, c) => s + (c.result === 'pass' ? c.weight : c.result === 'warn' ? c.weight / 2 : 0), 0);
  return { url, status, score: Math.round(100 * got / total), title, description, canonical, robots, h1: h1s[0] || '', h1_count: h1s.length,
    h2s: h2s.slice(0, 12), words, images: imgs.length, images_missing_alt: noAlt, internal_links: internal.length, external_links: external.length,
    internal_urls: internal.slice(0, 200), lang, schema: schemaTypes, keyword: kw, intro: text.slice(0, 700), checks: C,
    failed: C.filter(c => c.result !== 'pass').map(c => `${c.result.toUpperCase()}: ${c.label} (${c.detail})`) };
}

const page = $('Fetch page HTML').first().json;
const robots = $('Fetch robots.txt').first().json;
const input = $('Check the URL').first().json;
const ctype = String(page.headers?.['content-type'] || '');
const status = Number(page.statusCode || 0);
const robotsTxt = Number(robots.statusCode) === 200 && !/<html/i.test(String((robots.body ?? robots.data) || '')) ? String((robots.body ?? robots.data) || '') : '';
const loaded = status === 200 && /html/i.test(ctype || 'text/html') && String((page.body ?? page.data) || '').length > 200;
const s = analyse(page.body ?? page.data, input.url, status, input.keyword, robotsTxt);
return [{ json: { ...s, loaded, error: loaded ? '' : (status ? `The page returned HTTP ${status}${ctype && !/html/i.test(ctype) ? ' (' + ctype + ')' : ''}.` : (page.error?.message || 'The page could not be reached.')) } }];

parameters.text:
=You are a senior technical SEO consultant. Write a prioritised action plan for this page using ONLY the data below. Do not invent facts about the business (no prices, locations or claims that are not in the content).

URL: {{ $json.url }}
Target keyword: {{ $json.keyword || 'not given (infer the main topic from the content)' }}
Score: {{ $json.score }}/100
Title: {{ $json.title }}
Meta description: {{ $json.description }}
H1: {{ $json.h1 }} ({{ $json.h1_count }} H1 tags)
H2s: {{ $json.h2s.join(' | ') }}
Word count: {{ $json.words }}
Structured data: {{ $json.schema.join(', ') || 'none' }}
Failed or warning checks:
{{ $json.failed.join('\n') || 'none' }}
Opening content: {{ $json.intro }}

Rules:
- top_fixes: 3 to 6 items, most important first, each fix concrete enough to do in under an hour. impact is high, medium or low.
- suggested_title: 30-60 characters. suggested_meta_description: 120-155 characters. Include the keyword naturally if one is given.
- content_gaps: up to 5 subtopics a searcher would expect that the page does not cover.
- summary: max 30 words.

parameters.jsonSchemaExample:
{
  "summary": "Solid technical basics, but the title is too short and the page lacks depth for the target keyword.",
  "top_fixes": [
    {
      "priority": 1,
      "issue": "Title is 18 characters",
      "fix": "Rewrite the title to lead with the main keyword and benefit",
      "impact": "high"
    }
  ],
  "suggested_title": "Emergency Plumber in Leeds | 24/7 Call-Outs in 60 Minutes",
  "suggested_meta_description": "Burst pipe or no hot water? Our Leeds plumbers arrive within 60 minutes, day or night. Fixed prices, no call-out fee. Call now.",
  "content_gaps": [
    "Pricing section",
    "Service area list"
  ]
}

