const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

// Render the audit as HTML (score, checks table, AI action plan)
const s = $('Extract on-page signals').first().json;
const ai = $json.output || {};
const colour = s.score >= 80 ? '#1a7f37' : s.score >= 60 ? '#b26b00' : '#c62828';
const icon = r => r === 'pass' ? '&#10004;' : r === 'warn' ? '&#9888;' : '&#10008;';
const rows = s.checks.map(c => `<tr><td>${icon(c.result)}</td><td>${esc(c.label)}</td><td>${esc(c.detail)}</td></tr>`).join('');
const fixes = (ai.top_fixes || []).sort((a, b) => a.priority - b.priority)
  .map(f => `<li><b>${esc(f.issue)}</b> (${esc(f.impact)} impact): ${esc(f.fix)}</li>`).join('');
const t = String(ai.suggested_title || ''), d = String(ai.suggested_meta_description || '');
const html = `<h2 style="color:${colour}">SEO score: ${s.score}/100</h2><p><a href="${esc(s.url)}">${esc(s.url)}</a></p>
<p>${esc(ai.summary || '')}</p><h3>Fix these first</h3><ol>${fixes}</ol>
<h3>Suggested title (${t.length} chars)</h3><p>${esc(t)}</p><h3>Suggested meta description (${d.length} chars)</h3><p>${esc(d)}</p>
${(ai.content_gaps || []).length ? `<h3>Content gaps</h3><ul>${ai.content_gaps.map(g => `<li>${esc(g)}</li>`).join('')}</ul>` : ''}
<h3>All checks</h3><table style="width:100%;border-collapse:collapse;font-size:13px">${rows}</table>`;
return [{ json: { html, score: s.score, url: s.url } }];
